LANGS_2 = [("ja", ja), ("ru", ru), ("hi", hi), ("ar", ar)]

def js_lang(code, d):
    parts = []
    for k, v in d.items():
        parts.append(f"{k}:{json.dumps(v, ensure_ascii=False)}")
    return f"{code}:{{{','.join(parts)}}}"

open("/tmp/i18n_part2.json", "w").write(json.dumps(
    {code: js_lang(code, d) for code, d in LANGS_2}, ensure_ascii=False))
